            color = g[r - 1][c]
            if color and g[r][c] == 0 and g[r + 1][c] == color:
                vertical.append((r, c, color))
                g[r][c] = color

    # A broken bar's missing cell is its ray's intersection: fill toward the
    # complementary bar, preserving other original colored objects.
    for r, c, color in horizontal:
        targets = [rr for rr, cc, _ in vertical if cc == c]
        if targets:
            tr = min(targets, key=lambda rr: abs(rr - r))
