 "content": "def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])

    # Broken horizontal bars each contain exactly one missing cell. Complete
    # them and record their row, gap column, and color.
    bars = []
    for r in range(h):
        nz = [(c, g[r][c]) for c in range(w) if g[r][c] != 0]
        if len(nz) < 2 or len({v for _, v in nz}) != 1:
            continue
        color = nz[0][1]
        left, right = nz[0][0], nz[-1][0]
        gaps = [c for c in range(left + 1, right) if g[r][c] == 0]
        if len(gaps) == 1:
            c = gaps[0]
            bars.append((r, c, color))
            g[r][c] = color

    # For each bar, its gap column is a vertical guide line. Fill the segment
    # from that horizontal bar toward the nearest original marker of any color.
    # Above the bar, the guide marker's color is extended to the top boundary;
    # below it, the bar's color fills down to the nearest marker (or edge).
    for r, c, bar_color in bars:
        original_marks = [(rr, grid[rr][c]) for rr in range(h) if grid[rr][c] != 0]
        above = [(rr, color) for rr, color in original_marks if rr < r]
        below = [(rr, color) for rr, color in original_marks if rr > r]

        # Marker(s) above: extend its color upward to edge; bar color fills gap.
        if above:
            mr, marker_color = max(above)
            for rr in range(mr + 1, r):
                if g[rr][c] == 0:
                    g[rr][c] = bar_color
            for rr in range(mr):
                if g[rr][c] == 0:
                    g[rr][c] = marker_color
        # No marker above: bar color travels upward to the edge.
        else:
            for rr in range(r):
                if g[rr][c] == 0:
                    g[rr][c] = bar_color

        # Marker below: bar color fills down to it and marker color continues.
        if below:
            mr, marker_color = min(below)
            for rr in range(r + 1, mr):
                if g[rr][c] == 0:
                    g[rr][c] = bar_color
            for rr in range(mr + 1, h):
                if g[rr][c] == 0:
                    g[rr][c] = marker_color
        # No marker below: bar color continues to the edge.
        else:
            for rr in range(r + 1, h):
                if g[rr][c] == 0:
                    g[rr][c] = bar_color

    # Complete all internal gaps in each horizontal bar, including bars with
    # more than one missing cell; the gap-column detection above drives fills.
    for r in range(h):
        nz = [(c, g[r][c]) for c in range(w) if g[r][c] != 0]
        if len(nz) >= 2 and len({v for _, v in nz}) == 1:
            color = nz[0][1]
            for c in range(nz[0][0], nz[-1][0] + 1):
                if g[r][c] == 0:
                    g[r][c] = color
    return g
