 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Identify each horizontal segment's one-cell break. The break column is
    # the lane through which its color is extended toward the matching vertical
    # guide/bar, while the guide's color is extended on the far side.
    bars = []  # (row, gap_col, color)
    for r in range(h):
        vals = [(c, grid[r][c]) for c in range(w) if grid[r][c] != 0]
        if len(vals) < 2 or len({v for _, v in vals}) != 1:
            continue
        color = vals[0][1]
        left, right = vals[0][0], vals[-1][0]
        gaps = [c for c in range(left + 1, right) if grid[r][c] == 0]
        for c in gaps:
            bars.append((r, c, color))
            out[r][c] = color

    for r, c, bar_color in bars:
        marks = [(rr, grid[rr][c]) for rr in range(h) if grid[rr][c] != 0]
        above = [(rr, color) for rr, color in marks if rr < r]
        below = [(rr, color) for rr, color in marks if rr > r]

        # First guide above the stripe: its color rises to the top, and the
        # stripe color fills from the stripe up to that guide.
        if above:
            mr, guide_color = max(above)
            for rr in range(mr + 1, r):
                if out[rr][c] == 0:
                    out[rr][c] = bar_color
            for rr in range(mr):
                if out[rr][c] == 0:
                    out[rr][c] = guide_color
        else:
            for rr in range(r):
                if out[rr][c] == 0:
                    out[rr][c] = bar_color

        # First guide below the stripe: stripe color runs down to it, then
        # guide color continues to the bottom edge.
        if below:
            mr, guide_color = min(below)
            for rr in range(r + 1, mr):
                if out[rr][c] == 0:
                    out[rr][c] = bar_color
            for rr in range(mr + 1, h):
                if out[rr][c] == 0:
                    out[rr][c] = guide_color
        else:
            for rr in range(r + 1, h):
                if out[rr][c] == 0:
                    out[rr][c] = bar_color

    # Finish each horizontal stripe's gaps after extending the crossing lanes.
    for r in range(h):
        vals = [(c, grid[r][c]) for c in range(w) if grid[r][c] != 0]
        if len(vals) >= 2 and len({v for _, v in vals}) == 1:
            color = vals[0][1]
            for c in range(vals[0][0], vals[-1][0] + 1):
                if out[r][c] == 0:
                    out[r][c] = color
    return out
