            gaps = [c for c in range(left + 1, right) if grid[r][c] == 0]
            if gaps:
                hbars.append((r, left, right, color, gaps))
                for c in range(left, right + 1):
                    out[r][c] = color

    # Identify broken monochrome vertical bars.
    for c in range(w):
        cells = [(r, grid[r][c]) for r in range(h) if grid[r][c] != 0]
        if len(cells) >= 2 and len({v for _, v in cells}) == 1:
            color = cells[0][1]
