            gaps = [r for r in range(top + 1, bottom) if grid[r][c] == 0]
            if gaps:
                vbars.append((c, top, bottom, color, gaps))
                for r in range(top, bottom + 1):
                    out[r][c] = color

    # Horizontal gaps point to a vertical line column. Fill from the highest
    # broken stripe upward using its color, and from each crossing down to the
    # next one using the crossing color; vertical guide colors remain on given cells.
    for r, left, right, color, gaps in hbars:
