                if out[rr][c] == 0:
                    out[rr][c] = color

    # A broken vertical bar supplies a horizontal guide color across its gap row.
    # Fill until the horizontal bar's end, leaving source horizontal colors intact.
    for c, top, bottom, color, gaps in vbars:
