    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Each broken horizontal stripe is completed. The missing cell marks the
    # column of a vertical crossing; adjacent broken stripes in that lane
    # determine the colors of the vertical segments between their rows.
    bars = []
    for r in range(h):
        cells = [(c, grid[r][c]) for c in range(w) if grid[r][c] != 0]
        if len(cells) < 2 or len({v for _, v in cells}) != 1:
            continue
        color = cells[0][1]
        left, right = cells[0][0], cells[-1][0]
        gaps = [c for c in range(left + 1, right) if grid[r][c] == 0]
        if not gaps:
            continue
        bars.append((r, left, right, color, gaps))
        for c in range(left, right + 1):
            out[r][c] = color

    lanes = {}
    for r, _, _, color, gaps in bars:
        for c in gaps:
            lanes.setdefault(c, []).append((r, color))

    for c, events in lanes.items():
        events.sort()
        # Extend the highest horizontal stripe color to the top edge.
        first_r, first_color = events[0]
        for rr in range(first_r):
            out[rr][c] = first_color

        # Fill between consecutive broken stripes using the lower stripe's color.
        for i in range(len(events) - 1):
            r0, _ = events[i]
            r1, lower_color = events[i + 1]
            for rr in range(r0 + 1, r1):
                out[rr][c] = lower_color

        # Below the final horizontal stripe, its color reaches the nearest
        # original vertical guide; the guide's color continues below that mark.
        last_r, last_color = events[-1]
        guide = next(((rr, grid[rr][c]) for rr in range(last_r + 1, h)
