        if guide is not None:
            guide_r, guide_color = guide
            for rr in range(last_r + 1, guide_r):
                out[rr][c] = last_color
            for rr in range(guide_r + 1, h):
                out[rr][c] = guide_color
        else:
            for rr in range(last_r + 1, h):
                out[rr][c] = last_color

