    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # A one-cell break in a monochrome horizontal stripe marks a vertical lane.
    bars = []
    for r in range(h):
        cells = [(c, grid[r][c]) for c in range(w) if grid[r][c] != 0]
        if len(cells) < 2 or len({v for _, v in cells}) != 1:
            continue
        color = cells[0][1]
        left, right = cells[0][0], cells[-1][0]
        gaps = [c for c in range(left + 1, right) if grid[r][c] == 0]
        if gaps:
            bars.append((r, left, right, color, gaps))
            for c in range(left, right + 1):
                out[r][c] = color

    lanes = {}
    for r, _, _, color, gaps in bars:
        for c in gaps:
            lanes.setdefault(c, []).append((r, color))

    # Extend each horizontal stripe's color vertically between crossings. If
    # a vertical guide marker lies beyond the last crossing, continue its color
    # from there to the edge. Existing colored cells are retained.
    for c, events in lanes.items():
        events.sort()
        first_r, first_color = events[0]
        for rr in range(first_r):
            if out[rr][c] == 0:
                out[rr][c] = first_color
        for i, (r, color) in enumerate(events):
            next_r = events[i + 1][0] if i + 1 < len(events) else h
            for rr in range(r + 1, next_r):
                if out[rr][c] == 0:
                    out[rr][c] = color
        last_r, last_color = events[-1]
        below = [(rr, grid[rr][c]) for rr in range(last_r + 1, h) if grid[rr][c] != 0]
        if below:
            marker_r, marker_color = below[0]
            for rr in range(marker_r + 1, h):
                if out[rr][c] == 0:
                    out[rr][c] = marker_color

    return out
