 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Horizontal lines with single gaps indicate columns where vertical lines
    # cross. Each horizontal segment's color extends through the gap in its row.
    horizontal = []
    for r in range(h):
        for c in range(1, w - 1):
            color = grid[r][c - 1]
            if color and grid[r][c] == 0 and grid[r][c + 1] == color:
                out[r][c] = color
                horizontal.append((r, c, color))

    # Vertical isolated bars indicate the columns for corresponding crossings.
    # Extend each marked column up and down, switching to horizontal-bar colors
    # at their rows. Original bar colors are preserved where present.
    cols = {c for _, c, _ in horizontal}
    for c in cols:
        events = [(r, color) for r, cc, color in horizontal if cc == c]
        events.sort()
        originals = [(r, grid[r][c]) for r in range(h) if grid[r][c] != 0]
        # In this pattern, all nonzero cells in this column form the other
        # vertical guide(s), and the horizontal rows provide intervening colors.
        sources = sorted(events + originals)
        if not sources:
            continue
        # Color the vertical lane according to the closest source below each row;
        # at equal-distance ties, favor the horizontal crossing event.
        for rr in range(h):
            if grid[rr][c] != 0:
                out[rr][c] = grid[rr][c]
                continue
            candidates = sorted(sources, key=lambda item: (abs(item[0] - rr), 0 if item in events else 1))
            out[rr][c] = candidates[0][1]

    # Fill any remaining horizontal one-cell gaps in same-color runs.
    for r in range(h):
        for c in range(1, w - 1):
            color = grid[r][c - 1]
            if color and grid[r][c] == 0 and grid[r][c + 1] == color:
                out[r][c] = color
    return out

