    out = [row[:] for row in grid]

    # Horizontal stripes have a single missing cell; fill that cell and extend
    # its color vertically upward until the next stripe, and down to the next.
    bars = []
    for r in range(h):
        vals = [(c, grid[r][c]) for c in range(w) if grid[r][c] != 0]
        if len(vals) < 2 or len({v for _, v in vals}) != 1:
            continue
        color = vals[0][1]
        left, right = vals[0][0], vals[-1][0]
        gaps = [c for c in range(left + 1, right) if grid[r][c] == 0]
        if gaps:
            bars.append((r, left, right, color, gaps))
            for c in range(left, right + 1):
                if out[r][c] == 0:
                    out[r][c] = color

    lane_events = {}
    for r, _, _, color, gaps in bars:
        for c in gaps:
            lane_events.setdefault(c, []).append((r, color))

    for c, events in lane_events.items():
        events.sort()
        for i, (r, color) in enumerate(events):
            start = 0 if i == 0 else events[i-1][0] + 1
            end = events[i+1][0] if i+1 < len(events) else h
            for rr in range(start, end):
                # Preserve the source vertical bars at the far bottom, but use
                # stripe colors elsewhere. A new event below changes color.
                if grid[rr][c] != 0 and rr > events[-1][0]:
                    continue
                out[rr][c] = color

    # Extend aligned vertical guide bars through rows between their source cells.
    # Their original color continues outside the outermost horizontal bands.
    for c in range(w):
        vals = [(r, grid[r][c]) for r in range(h) if grid[r][c] != 0]
        if len(vals) >= 2 and len({v for _, v in vals}) == 1:
            color = vals[0][1]
            # In the demonstrations the vertical guide's color is retained on
            # the row immediately after the last horizontal bar; don't overwrite
            # horizontal stripes or intervening stripe-color lanes.
            for r in range(vals[0][0], vals[-1][0] + 1):
                if out[r][c] == 0:
                    out[r][c] = color
    return out
