 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Find broken horizontal bars: each gap column marks an intersection.
    horizontal = []
    for r in range(h):
        cells = [(c, grid[r][c]) for c in range(w) if grid[r][c]]
        if len(cells) < 2 or len({v for _, v in cells}) != 1:
            continue
        color = cells[0][1]
        left, right = cells[0][0], cells[-1][0]
        gaps = [c for c in range(left + 1, right) if grid[r][c] == 0]
        if gaps:
            horizontal.append((r, left, right, color, gaps))

    # Find broken vertical bars as well.
    vertical = []
    for c in range(w):
        cells = [(r, grid[r][c]) for r in range(h) if grid[r][c]]
        if len(cells) < 2 or len({v for _, v in cells}) != 1:
            continue
        color = cells[0][1]
        top, bottom = cells[0][0], cells[-1][0]
        gaps = [r for r in range(top + 1, bottom) if grid[r][c] == 0]
        if gaps:
            vertical.append((c, top, bottom, color, gaps))

    # Complete every broken horizontal and vertical stroke.
    for r, left, right, color, _ in horizontal:
        for c in range(left, right + 1):
            if out[r][c] == 0:
                out[r][c] = color
    for c, top, bottom, color, _ in vertical:
        for r in range(top, bottom + 1):
            if out[r][c] == 0:
                out[r][c] = color

    # Horizontal breaks identify vertical columns: extend each horizontal color
    # along the column up to the next crossing, and from the nearest bottom guide.
    by_col = {}
    for r, _, _, color, gaps in horizontal:
        for c in gaps:
            by_col.setdefault(c, []).append((r, color))
    for c, marks in by_col.items():
        marks.sort()
        # Fill above first horizontal crossing in its own color.
        r0, color0 = marks[0]
        for rr in range(r0):
            out[rr][c] = color0
        # Between consecutive crossings, use the lower crossing's color.
        for i in range(len(marks) - 1):
            ra, _ = marks[i]
            rb, color_b = marks[i + 1]
            for rr in range(ra + 1, rb):
                out[rr][c] = color_b
        # Below the final crossing, use that crossing color to the next guide;
        # then carry the guide's own color to the bottom edge.
        rl, color_l = marks[-1]
        lower_guides = [(rr, grid[rr][c]) for rr in range(rl + 1, h) if grid[rr][c] != 0]
        if lower_guides:
            guide_r, guide_color = lower_guides[0]
            for rr in range(rl + 1, guide_r):
                out[rr][c] = color_l
            for rr in range(guide_r + 1, h):
                out[rr][c] = guide_color

    # Vertical breaks identify horizontal rows. The guide color fills its row
    # from the vertical line toward the matching horizontal bar, while retaining
    # horizontal-bar color on the bar row itself.
    for c, top, bottom, color, gaps in vertical:
        for r in gaps:
            matching = [hb for hb in horizontal if hb[0] == r]
            if matching:
                _, left, right, _, _ = matching[0]
                for cc in range(left, right + 1):
                    if out[r][cc] == 0:
                        out[r][cc] = color
    return out
