 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    lanes = {}

    # Each horizontal one-cell gap marks a vertical color lane.
    # Record the gap's row and the matching horizontal-bar color.
    for r in range(h):
        for c in range(1, w - 1):
            color = grid[r][c - 1]
            if color != 0 and grid[r][c] == 0 and grid[r][c + 1] == color:
                lanes.setdefault(c, []).append((r, color))
                out[r][c] = color

    for c, events in lanes.items():
        events.sort()
        # At each crossing, the current horizontal bar's color fills upward
        # from the prior crossing (or the top edge) through its own row.
        for i, (r, color) in enumerate(events):
            start = 0 if i == 0 else events[i - 1][0] + 1
            for rr in range(start, r + 1):
                out[rr][c] = color

        # Below the lowest horizontal crossing, extend the nearest vertical
        # marker's color along the rest of the column.
        last_r, last_color = events[-1]
        guide = next((grid[rr][c] for rr in range(last_r + 1, h)
                      if grid[rr][c] != 0), None)
        fill_color = guide if guide is not None else last_color
        for rr in range(last_r + 1, h):
            out[rr][c] = fill_color

