        if gaps:
            bars.append((r, color, gaps))
            for c in range(left, right + 1):
                out[r][c] = color

    # On each gap lane, colors propagate according to the horizontal stripe
    # crossings: first stripe color extends to the top, then each lower stripe
    # color fills the interval up to the next crossing. Bottom guide pixels remain.
    lanes = {}
