    for r in range(h):
        vals = [(c, grid[r][c]) for c in range(w) if grid[r][c]]
        if len(vals) < 2 or len({v for _, v in vals}) != 1:
            continue
        color = vals[0][1]
        left, right = vals[0][0], vals[-1][0]
        gaps = [c for c in range(left + 1, right) if grid[r][c] == 0]
        if gaps:
            hbars.append((r, color, gaps))
            for c in range(left, right + 1):
                out[r][c] = color

    # Broken vertical stripes are explicit guides (e.g. 1/5 in demo, 6/8 here).
    vguides = {}
    for c in range(w):
        vals = [(r, grid[r][c]) for r in range(h) if grid[r][c]]
        if len(vals) >= 2 and len({v for _, v in vals}) == 1:
            color = vals[0][1]
            vguides[c] = (vals[0][0], vals[-1][0], color)

    # Gap columns are colored by the horizontal strokes: first color above the
    # first crossing, then the lower stroke's color in each intervening interval.
    lanes = {}
    for r, color, gaps in hbars:
        for c in gaps:
            lanes.setdefault(c, []).append((r, color))
