        events.sort()
        r0, col0 = events[0]
        for rr in range(r0):
            out[rr][c] = col0
        for i in range(1, len(events)):
            r, col = events[i]
            prev = events[i - 1][0]
            for rr in range(prev + 1, r):
                out[rr][c] = col
        last_r, last_col = events[-1]
        # The last horizontal stroke's color extends to the lower vertical guide;
        # then the guide's own color continues down to its endpoint.
        guide = vguides.get(c)
        if guide:
            top, bottom, guide_col = guide
            for rr in range(last_r + 1, top):
                out[rr][c] = last_col
            for rr in range(top, bottom + 1):
                out[rr][c] = guide_col
        else:
            for rr in range(last_r + 1, h):
                out[rr][c] = last_col

    # Extend vertical guide colors upward to the first relevant horizontal bar;
    # for the part below the lowest horizontal bar, retain the guide as given.
    for c, (top, bottom, color) in vguides.items():
        for rr in range(top, bottom + 1):
