    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Horizontal broken bars specify vertical lanes; complete their holes.
    bars = []
    for r in range(h):
        cells = [(c, grid[r][c]) for c in range(w) if grid[r][c]]
        if len(cells) < 2 or len({v for _, v in cells}) != 1:
            continue
        color = cells[0][1]
        left, right = cells[0][0], cells[-1][0]
        gaps = [c for c in range(left + 1, right) if grid[r][c] == 0]
        if gaps:
            bars.append((r, color, gaps))
            for c in range(left, right + 1):
                out[r][c] = color

    # Vertical guide bars are the monochrome columns with repeated markers.
    guides = {}
    for c in range(w):
        cells = [(r, grid[r][c]) for r in range(h) if grid[r][c]]
        if len(cells) >= 2 and len({v for _, v in cells}) == 1:
            guides[c] = cells[0][1]

    lanes = {}
    for r, color, gaps in bars:
        for c in gaps:
            lanes.setdefault(c, []).append((r, color))

    for c, events in lanes.items():
        events.sort()
        # The upper vertical section carries the top horizontal stripe's color.
        r0, col0 = events[0]
        for rr in range(r0):
            out[rr][c] = col0

        # Between stripe crossings, the color is that of the lower stripe.
        for i in range(1, len(events)):
            r, color = events[i]
            prev = events[i - 1][0]
            for rr in range(prev + 1, r):
                out[rr][c] = color

        # Beneath the lowest horizontal crossing, extend the lower stripe color
        # until the vertical guide's source, then continue the guide color below.
        last_r, last_color = events[-1]
        guide_rows = [rr for rr in range(last_r + 1, h) if grid[rr][c] != 0]
        if guide_rows:
            source_r = guide_rows[0]
            guide_color = grid[source_r][c]
            for rr in range(last_r + 1, source_r):
                out[rr][c] = last_color
            for rr in range(source_r + 1, h):
                out[rr][c] = guide_color
        else:
            for rr in range(last_r + 1, h):
                out[rr][c] = last_color

    # Each line continues to the edge only in the direction indicated by its
    # terminal segments; explicit original cells are never lost.
    return out


