        gaps = [c for c in range(left + 1, right) if grid[r][c] == 0]
        if gaps:
            bars.append((r, color, gaps))
            for c in range(left, right + 1):
                out[r][c] = color

    # Vertical original bars/markers set their columns. For each crossing
    # column, the stripes' colors extend up/down until crossing another stripe.
    lanes = {}
    for r, color, gaps in bars:
        for c in gaps:
            lanes.setdefault(c, []).append((r, color))

